WH.setPageData("wow.talentCalcClassic.mists.data",{"talents":{"11":{"102":[131768,102280,102401,145108,108238,102351,106707,102359,132469,114107,106731,106737,99,102793,5211,108288,108373,124974],"103":[131768,102280,102401,145108,108238,102351,106707,102359,132469,114107,106731,106737,99,102793,5211,108288,108373,124974],"104":[131768,102280,102401,145108,108238,102351,106707,102359,132469,114107,106731,106737,99,102793,5211,108288,108373,124974],"105":[131768,102280,102401,145108,108238,102351,106707,102359,132469,114107,106731,106737,99,102793,5211,108288,108373,124974]},"4":{"259":[14062,108208,108209,26679,108210,74001,31230,108211,79008,138106,36554,108212,131511,108215,108216,114014,137619,114015],"260":[14062,108208,108209,26679,108210,74001,31230,108211,79008,138106,36554,108212,131511,108215,108216,114014,137619,114015],"261":[14062,108208,108209,26679,108210,74001,31230,108211,79008,138106,36554,108212,131511,108215,108216,114014,137619,114015]}}});
WH.Gatherer.addData(6, 15, {"14062":{"name_enus":"Nightstalker","icon":"ability_stealth","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Passive Talent","description_enus":"Increases your movement speed while stealthed by 20%, and the damage your abilities deal while stealthed by 50%."},"108208":{"name_enus":"Subterfuge","icon":"rogue_subterfuge","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Your Stealth breaks 3 sec after dealing or receiving hostile actions, rather than doing so immediately."},"108209":{"name_enus":"Shadow Focus","icon":"rogue_shadowfocus","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Abilities cost 75% less Energy while you are stealthed."},"26679":{"name_enus":"Deadly Throw","icon":"inv_throwingknife_06","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Talent","description_enus":"Finishing move that reduces the movement speed of the target by 50% for 6 sec.  If performed with 3 combo points, also interrupts spellcasting and prevents any spell in that school from being cast for a period of time.<br />Damage dealt:<br />   1 point  : [<!--pts1:1:0:26679-->268<!----> + (0 + Attack Power * 0.12) * <!--sp76808:0-->1<!--sp76808-->]-[<!--pts1:2:0:26679-->801<!----> + (0 + Attack Power * 0.12) * <!--sp76808:0-->1<!--sp76808-->] damage<br />   2 points: [<!--pts1:1:0:26679-->268<!----> + ((0) + Attack Power * 0.24) * <!--sp76808:0-->1<!--sp76808-->]-[<!--pts1:2:0:26679-->801<!----> + ((0) + Attack Power * 0.24) * <!--sp76808:0-->1<!--sp76808-->] damage<br />   3 points: [<!--pts1:1:0:26679-->268<!----> + ((0) + Attack Power * 0.36) * <!--sp76808:0-->1<!--sp76808-->]-[<!--pts1:2:0:26679-->801<!----> + ((0) + Attack Power * 0.36) * <!--sp76808:0-->1<!--sp76808-->] damage<br />   4 points: [<!--pts1:1:0:26679-->268<!----> + ((0) + Attack Power * 0.48) * <!--sp76808:0-->1<!--sp76808-->]-[<!--pts1:2:0:26679-->801<!----> + ((0) + Attack Power * 0.48) * <!--sp76808:0-->1<!--sp76808-->] damage<br />   5 points: [<!--pts1:1:0:26679-->268<!----> + ((0) + Attack Power * 0.6) * <!--sp76808:0-->1<!--sp76808-->]-[<!--pts1:2:0:26679-->801<!----> + ((0) + Attack Power * 0.6) * <!--sp76808:0-->1<!--sp76808-->] damage"},"108210":{"name_enus":"Nerve Strike","icon":"rogue_nerve-_strike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Passive Talent","description_enus":"<a href=\"/mop-classic/spell=112947/nerve-strike\" target=\"_blank\">A successful Kidney Shot or Cheap Shot also reduces the damage dealt by the target by 50% (25% on player targets) and healing done by the target by 10% for 6 sec after the effect fades.</a>"},"74001":{"name_enus":"Combat Readiness","icon":"ability_rogue_combatreadiness","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Enter into a state of heightened awareness, deflecting enemy weapon strikes with increasing effectiveness.  Successive attacks will deal 10% less damage per application, stacking 5 times.<br /><br />Lasts for 20 sec, but if 10 sec elapse without any incoming weapon strikes, this state will end."},"31230":{"name_enus":"Cheat Death","icon":"ability_rogue_cheatdeath","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Passive Talent","description_enus":"An attack that would otherwise be fatal will instead reduce you to no less than 10% of your maximum health, and damage taken will be reduced by 85% for 3 sec.  This effect cannot occur more than once per 90 seconds."},"108211":{"name_enus":"Leeching Poison","icon":"rogue_leeching_poison","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Coats your weapons with a Non-Lethal Poison that lasts for 1 hour.  Your melee attacks have a 50% chance to poison the target for 10 sec. Your subsequent weapon strikes against the poisoned target will heal you for 10% of damage dealt. [<span class='q2'>Shiv</span>: <span class='q9'><span style=\"color: #FFFFFF\">Shiv Effect:</span> <br />Instantly restores 5% of the Rogue's health</span>]"},"79008":{"name_enus":"Elusiveness","icon":"ability_rogue_turnthetables","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Passive Talent","description_enus":"Your Feint ability also reduces all damage taken by 30% for 5 sec."},"138106":{"name_enus":"Cloak and Dagger","icon":"ability_rogue_unfairadvantage","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Your Ambush, Garrote, and Cheap Shot abilities can now be used from 40 yards away, and will cause you to appear behind your target."},"36554":{"name_enus":"Shadowstep","icon":"ability_rogue_shadowstep","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Step through the shadows and appear behind a target.  Movement speed is increased by 70% for 2 sec afterwards."},"108212":{"name_enus":"Burst of Speed","icon":"rogue_burstofspeed","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases movement speed by 70% for 4 sec and removes any movement-slowing effects. Does not break stealth."},"131511":{"name_enus":"Prey on the Weak","icon":"ability_rogue_preyontheweak","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When you disable an enemy with Kidney Shot, Cheap Shot, Gouge, Sap, or Blind, they suffer 10% increased damage from all sources for the duration of the effect."},"108215":{"name_enus":"Paralytic Poison","icon":"rogue_paralytic_poison","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Coats your weapons with a Non-Lethal Poison that lasts for 1 hour.  Each strike has a 20% chance of poisoning the enemy for 15 sec.  Stacks up to 4 times on a single target, and upon a fourth application, the enemy will be stunned for 4 seconds. [<span class='q2'>Shiv</span>: <span class='q9'><span style=\"color: #FFFFFF\">Shiv Effect:</span> <br />Causes instant paralysis of an enemy's lower body, rooting them in place for 4 sec</span>]"},"108216":{"name_enus":"Dirty Tricks","icon":"ability_rogue_dirtydeeds","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Passive Talent","description_enus":"Your Gouge and Blind no longer have an Energy cost, and no longer break from damage dealt by your Poison and Bleed effects."},"114014":{"name_enus":"Shuriken Toss","icon":"inv_throwingknife_07","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"A ranged attack that deals <!--pts1:0:0:114014-->2493<!----> Physical damage to an enemy target. If the enemy is farther than 10 yards away, your autoattacks will be replaced with ranged shuriken for up to 10 sec, granting them a 30 yd range. Shurikens are coated in your Lethal Poison. Awards 1 combo <!--singular:point:points-->point<!--singular-->. <br /><br />Replaces Throw."},"137619":{"name_enus":"Marked for Death","icon":"achievement_bg_killingblow_berserker","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Mark the target, instantly generating 5 combo points on them. If the target dies within 1 min Marked for Death's cooldown is reset."},"114015":{"name_enus":"Anticipation","icon":"ability_rogue_slaughterfromtheshadows","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When one of your attacks generates a combo point on a target that already has 5 combo points, you gain an Anticipation charge, up to a maximum of 5.<br /><br />When you perform an offensive finishing move on an enemy, any Anticipation charges are consumed to grant you an equal number of combo points on that target."},"131768":{"name_enus":"Feline Swiftness","icon":"spell_druid_tirelesspursuit","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases your movement speed by 15%."},"102280":{"name_enus":"Displacer Beast","icon":"spell_druid_displacement","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Teleports the Druid up to 20 yards forward, activates Cat Form, and increases movement speed by 50% for 4 sec."},"102401":{"name_enus":"Wild Charge","icon":"spell_druid_wildcharge","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Fly to a nearby ally's position."},"145108":{"name_enus":"Ysera's Gift","icon":"inv_misc_head_dragon_green","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Every 5 sec, heals you for 5% of your maximum health.  If you are at full health, the most injured nearby ally will be healed instead."},"108238":{"name_enus":"Renewal","icon":"spell_nature_natureblessing","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Instantly heals the Druid for 30% of maximum health.  Useable in all shapeshift forms."},"102351":{"name_enus":"Cenarion Ward","icon":"ability_druid_naturalperfection","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Protects a friendly target, causing any damage taken to heal the target for <!--pts1:0:0:102352-->12349<!----> every 2 sec for 6 sec.  Gaining the healing effect consumes the Cenarion Ward.  Useable in all shapeshift forms.  Lasts 30 sec."},"106707":{"name_enus":"Faerie Swarm","icon":"spell_druid_swarm","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Grants an improved version of Faerie Fire that also reduces the target's movement speed by 50% for 15 sec.<br /><br />This talent replaces Faerie Fire."},"102359":{"name_enus":"Mass Entanglement","icon":"spell_druid_massentanglement","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Roots your target in place for 20 sec and spreads to additional nearby enemies.  Damage caused may interrupt the effect.  Useable in all shapeshift forms."},"132469":{"name_enus":"Typhoon","icon":"ability_druid_typhoon","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Summons a violent Typhoon that strikes targets in front of the caster within 30 yards, knocking them back and dazing them for 6 sec.  Useable in all shapeshift forms."},"114107":{"name_enus":"Soul of the Forest","icon":"ability_druid_manatree","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Aessina's blessing grants a benefit which varies by your combat specialization.<br /><br /><span style=\"color: #FFFFFF\">Balance</span><br />Your Wrath, Starfire, and Starsurge casts have a 8% chance to cause your next Astral Communion to instantly grant 100 Lunar or Solar Power.<br /><br /><span style=\"color: #FFFFFF\">Feral</span><br />Your finishing moves grant 4 Energy per combo point.<br /><br /><span style=\"color: #FFFFFF\">Guardian</span><br />Mangle (Bear) now generates 30% more Rage and deals 15% more damage.<br /><br /><span style=\"color: #FFFFFF\">Restoration</span><br />You gain 100% haste for your next spell when you cast Swiftmend."},"106731":{"name_enus":"Incarnation","icon":"spell_druid_incarnation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Grants a superior shapeshifting form appropriate to your specialization for 30 sec.  You may freely shapeshift in and out of this form for the duration of Incarnation.<br /><br /><span style=\"color: #FFFFFF\">Balance: Chosen of Elune</span><br />Improved Moonkin Form that gains 25% increased Arcane and Nature damage while Eclipse is active.<br /><br /><span style=\"color: #FFFFFF\">Feral: King of the Jungle</span><br />Improved Cat Form that allows the use of all abilities which normally require stealth, allows the use of Prowl while in combat, and removes the positional requirement of Ravage.<br /><br /><span style=\"color: #FFFFFF\">Guardian: Son of Ursoc</span><br />Improved Bear Form that reduces the cooldown on melee damage abilities and Growl to 1.5 sec.<br /><br /><span style=\"color: #FFFFFF\">Restoration: Tree of Life</span><br />Tree of Life Form that increases healing done by 15%, increases armor by 120%, and enhances Lifebloom, Wild Growth, Regrowth, and Entangling Roots spellcasts."},"106737":{"name_enus":"Force of Nature","icon":"ability_druid_forceofnature","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Summons a Treant to assist in the Druid's current combat role for 15 sec.  Useable in all shapeshift forms.<br /><br /><span style=\"color: #FFFFFF\">Balance</span><br />Casts Wrath for [<!--pts1:1:0:1242002-->1930<!----> + (Spell Power * 0.375)]) to [<!--pts1:2:0:1242002-->2175<!----> + (Spell Power * 0.375)]) Nature damage every 2 sec and will cast Entangling Roots.<br />  <br /><span style=\"color: #FFFFFF\">Feral</span><br />Melees for (<!--pts1:1:0:102703-->2189<!----> + Attack Power / 14 * 2) Physical damage every 2 sec and will cast Entangling Roots and Rake.<br /><br /><span style=\"color: #FFFFFF\">Guardian</span><br />Melees for [(1 + Attack Power / 14 * 2 * 0.75) * 0.2 + 1] Physical damage every 2 sec and will use Taunt.<br /><br /><span style=\"color: #FFFFFF\">Restoration</span><br />Heals a nearby injured ally for <!--pts1:0:0:113828-->3490<!----> every 2.5 sec and will use Swiftmend."},"99":{"name_enus":"Disorienting Roar","icon":"classic_ability_druid_demoralizingroar","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Invokes the spirit of Ursol to roar, disorienting all enemies within 10 yards for 3 sec.  Any damage caused will remove the effect.  Useable in all shapeshift forms."},"102793":{"name_enus":"Ursol's Vortex","icon":"spell_druid_ursolsvortex","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Conjures a vortex of wind at the destination location that reduces the movement speed of all enemies within 8 yards by 50%.<br /><br />The first time an enemy attempts to leave the vortex, winds will pull that enemy back to its center.<br /><br />Lasts 10 sec.  Useable in all shapeshift forms."},"5211":{"name_enus":"Mighty Bash","icon":"ability_druid_bash","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Invokes the spirit of Ursoc to stun the target for 5 sec.  Useable in all shapeshift forms."},"108288":{"name_enus":"Heart of the Wild","icon":"spell_holy_blessingofagility","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"<span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/ability_racial_bearform.jpg)'></span> Guardian (<a href=\"/mop-classic/spell=137010/hotfix-passive\">Hotfix Passive</a>)<br />Increases Stamina, Agility, and Intellect by 6%.<br /><br />When activated, increases all healing done and dramatically improves the Druid's ability to perform roles outside of their specialization for 45 sec. While not in an Arena or Battleground, shifting into Bear Form removes Heart of the Wild, and if the Druid was not recently in Bear Form, the cooldown is refunded 4 sec for every 1 sec of unused duration.<br /><br />Grants the following benefits based on current specialization:<br /><br /><span style=\"color: #FFFFFF\">Non-Guardian</span><br />While in Bear Form, Agility, Expertise, Hit Chance, and armor bonuses increased, Vengeance granted, chance to be hit by melee critical strikes reduced.<br /><br /><span style=\"color: #FFFFFF\">Non-Feral</span><br />While in Cat Form, Agility, Hit Chance, and Expertise increased.<br /><br /><span style=\"color: #FFFFFF\">Non-Restoration</span><br />Mana cost of all healing spells reduced by 100%. Guardian Druids may also cast Rejuvenation while shapeshifted.<br /><br /><span style=\"color: #FFFFFF\">Non-Balance</span><br />Spell Damage and Hit Chance increased. Mana cost of all damage spells reduced by 100%.<br /><br /><span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/spell_nature_starfall.jpg)'></span> Balance, <span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/ability_druid_catform.jpg)'></span> Feral, <span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/spell_nature_healingtouch.jpg)'></span> Restoration<br />Increases Stamina, Agility, and Intellect by 6%.<br /><br />When activated, increases all healing done and dramatically improves the Druid's ability to perform roles outside of their specialization for 45 sec. [<span class='q2'><span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/ability_racial_bearform.jpg)'></span> Guardian</span>: <span class='q9'>While not in an Arena or Battleground, shifting into Bear Form removes Heart of the Wild, and if the Druid was not recently in Bear Form, the cooldown is refunded 4 sec for every 1 sec of unused duration</span>]<br /><br />Grants the following benefits based on current specialization:<br /><br /><span style=\"color: #FFFFFF\">Non-Guardian</span><br />While in Bear Form, Agility, Expertise, Hit Chance, and armor bonuses increased, Vengeance granted, chance to be hit by melee critical strikes reduced.<br /><br /><span style=\"color: #FFFFFF\">Non-Feral</span><br />While in Cat Form, Agility, Hit Chance, and Expertise increased.<br /><br /><span style=\"color: #FFFFFF\">Non-Restoration</span><br />Mana cost of all healing spells reduced by 100%. Guardian Druids may also cast Rejuvenation while shapeshifted.<br /><br /><span style=\"color: #FFFFFF\">Non-Balance</span><br />Spell Damage and Hit Chance increased. Mana cost of all damage spells reduced by 100%.<!--cooldown:137010:3 min cooldown-->"},"108373":{"name_enus":"Dream of Cenarius","icon":"ability_druid_dreamstate","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"<span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/ability_racial_bearform.jpg)'></span> Guardian (<a href=\"/mop-classic/spell=137010/hotfix-passive\">Hotfix Passive</a>)<br />The Emerald Dream grants a benefit which varies by your combat specialization.<br /><br /><span style=\"color: #FFFFFF\">Balance</span><br />Increases healing from Healing Touch by 20% and casting Healing Touch increases the damage bonus of your next Eclipse by 35%.<br /><br /><span style=\"color: #FFFFFF\">Feral</span><br />Increases healing from Healing Touch by 20% and casting Healing Touch causes your next two melee abilities to deal 40% additional damage.<br /><br /><span style=\"color: #FFFFFF\">Guardian</span><br />Increases healing from Healing Touch by 20%, Critical Strike chance of Mangle (Bear) by 10%, and your Mangle (Bear) critical strikes have a 50% chance to make your next Healing Touch or Rebirth instant, free, and castable in all forms, and benefit from Attack Power instead of Spell Power.<br /><br /><span style=\"color: #FFFFFF\">Restoration</span><br />Increases Wrath damage by 20% and your Wrath spell causes a nearby ally to be healed for 100% of the damage done.<br /><br /><span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/spell_nature_starfall.jpg)'></span> Balance, <span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/ability_druid_catform.jpg)'></span> Feral, <span class='tooltip-inside-icon' style='background-image: url(//wow.zamimg.com/images/wow/icons/small/spell_nature_healingtouch.jpg)'></span> Restoration<br />The Emerald Dream grants a benefit which varies by your combat specialization.<br /><br /><span style=\"color: #FFFFFF\">Balance</span><br />Increases healing from Healing Touch by 20% and casting Healing Touch increases the damage bonus of your next Eclipse by 25%.<br /><br /><span style=\"color: #FFFFFF\">Feral</span><br />Increases healing from Healing Touch by 20% and casting Healing Touch causes your next two melee abilities to deal 30% additional damage.<br /><br /><span style=\"color: #FFFFFF\">Guardian</span><br />Increases healing from Healing Touch by 20%, Critical Strike chance of Mangle (Bear) by 10%, and your Mangle (Bear) critical strikes have a 40% chance to make your next Healing Touch or Rebirth instant, free, and castable in all forms, and benefit from Attack Power instead of Spell Power.<br /><br /><span style=\"color: #FFFFFF\">Restoration</span><br />Increases Wrath damage by 20% and your Wrath spell causes a nearby ally to be healed for 100% of the damage done."},"124974":{"name_enus":"Nature's Vigil","icon":"achievement_zone_feralas","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases all damage and healing done by 12% for 30 sec.  While active, all single-target healing spells also damage a nearby enemy target for 25% of the healing done, and all single-target healing and damage spells and abilities also heal a nearby friendly target for 25% of the amount done."}});
